function assertDefault(html, selected, disabled = false) {
  assert.match(html, /<label for="default-task-priority">Default task priority<\/label>/);
  const select = html.match(/<select id="default-task-priority"[^>]*>([\s\S]*?)<\/select>/);
  assert.ok(select);
