import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const directory = await mkdtemp(join(tmpdir(), 'workboard-start-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') }, stdio: ['ignore', 'pipe', 'inherit'] });
try {
  const port = await new Promise((resolve, reject) => {
    let output = '';
    const timer = setTimeout(() => reject(new Error('Startup timed out')), 5000);
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/Workboard listening on 0\\.0\\.0\\.0:(\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
    child.once('error', reject);
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  const body = await response.text();
  if (response.status !== 200 || body !== '"'{\"status\":\"ok\"}') throw new Error("'`Unexpected health: ${response.status} ${body}`);
  console.log(`npm start: bound to 0.0.0.0; GET /health: ${response.status} ${body}`);
  // Stop the Node server directly so npm can exit and the database closes.
  const { execFileSync } = await import('"'node:child_process');
  execFileSync('pkill', ['-TERM', '-P', String(child.pid)]);
  await once(child, 'exit');
} finally {
  if (child.exitCode === null && child.signalCode === null) child.kill('SIGTERM');
  await rm(directory, { recursive: true, force: true });
}
